<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/seafort/app/bootstrap.php';
sf_admin_session();
if(empty($_SESSION['authenticated'])){header('Location: /admin/',true,303);exit;}
$language=is_string($_GET['lang']??null)&&isset(sf_translation_languages()[$_GET['lang']])?$_GET['lang']:'tr';
$query=is_string($_GET['q']??null)?trim(substr($_GET['q'],0,200)):'';
$page=max(1,(int)($_GET['page']??1));$error='';$notice='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
    try{
        sf_require_csrf();
        if(($_POST['action']??'')==='logout'){sf_logout();header('Location: /admin/',true,303);exit;}
        if(($_POST['action']??'')!=='save'||!is_array($_POST['entries']??null))throw new InvalidArgumentException('İşlem geçersiz.');
        sf_translation_save($language,$_POST['entries'],is_string($_POST['revision']??null)?$_POST['revision']:'');
        $notice='Çeviriler kaydedildi. Sayfayı yenileyerek kontrol edebilirsiniz.';
    }catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable){$error='Çeviriler kaydedilemedi. Mevcut içerik korunuyor.';}
}
$catalog=sf_translation_read($language);$filtered=array_filter($catalog,static fn($value,$key)=>$query===''||stripos($key,$query)!==false||stripos($value,$query)!==false,ARRAY_FILTER_USE_BOTH);
ksort($filtered);$total=count($filtered);$pages=max(1,(int)ceil($total/25));$page=min($page,$pages);$visible=array_slice($filtered,($page-1)*25,25,true);
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Çeviriler | Seafort</title><link rel="stylesheet" href="<?=sf_escape(sf_asset_url('/admin/admin.css'))?>"><link rel="stylesheet" href="<?=sf_escape(sf_asset_url('/admin/content.css'))?>"><link rel="stylesheet" href="<?=sf_escape(sf_asset_url('/admin/clarity.css'))?>"><link rel="stylesheet" href="<?=sf_escape(sf_asset_url('/admin/translations.css'))?>"><link rel="stylesheet" href="<?=sf_escape(sf_asset_url('/assets/fonts/brand-fonts.css'))?>"></head><body class="admin-shell">
<aside class="sidebar"><a class="sidebar-brand" href="/admin/"><img src="/assets/logo-white.png" alt="Seafort"></a><p class="sidebar-label">İÇERİK YÖNETİMİ</p><nav aria-label="Yönetim menüsü"><a class="side-link" href="/admin/">Blog yazıları</a><a class="side-link" href="/admin/enquiries.php">Formlar ve başvurular</a><a class="side-link" href="/admin/manage.php?type=projects">Projeler</a><a class="side-link" href="/admin/content.php?type=pages">Sayfa içerikleri</a><a class="side-link" href="/admin/documents.php">Belge merkezi</a><a class="side-link" href="/admin/references.php">Referanslar ve firmalar</a><a class="side-link active" href="/admin/translations.php">Çeviriler</a><a class="side-link" href="/admin/content.php?type=settings">İletişim ve WhatsApp</a></nav><div class="sidebar-bottom"><form method="post"><input type="hidden" name="csrf" value="<?=sf_escape(sf_csrf())?>"><input type="hidden" name="action" value="logout"><button class="logout">Oturumu kapat</button></form></div></aside>
<div class="admin-main"><header class="topbar"><p>SEAFORT / Çeviriler</p><a href="/?lang=<?=sf_escape($language)?>" target="_blank" rel="noopener">Sitede görüntüle</a></header><main class="workspace"><div class="page-heading"><div><p class="eyebrow">DİLLER</p><h1>Çeviriler</h1><p class="muted">İngilizce asıl metni ve karşılığını birlikte yönetin. Yeni İngilizce metin eklediğinizde çevirisini de burada ekleyin.</p></div></div>
<?php if($notice):?><div class="alert alert-success" role="status"><?=sf_escape($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-error" role="alert"><?=sf_escape($error)?></div><?php endif;?>
<section class="panel translation-panel"><form class="translation-search" method="get"><label>Dil<select name="lang"><?php foreach(sf_translation_languages() as $key=>$label):?><option value="<?=sf_escape($key)?>" <?=$key===$language?'selected':''?>><?=sf_escape($label)?></option><?php endforeach;?></select></label><label>Metin ara<input type="search" name="q" value="<?=sf_escape($query)?>"></label><button class="button button-ghost">Ara</button></form><p class="muted"><?=$total?> metin · Sayfa <?=$page?> / <?=$pages?></p></section>
<form method="post"><input type="hidden" name="csrf" value="<?=sf_escape(sf_csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="revision" value="<?=sf_escape(sf_content_digest($catalog))?>">
<?php $i=0;foreach($visible as $key=>$value):?><section class="panel translation-pair"><div><label for="translation-key-<?=$i?>">İngilizce asıl metin</label><textarea id="translation-key-<?=$i?>" name="entries[<?=$i?>][key]" readonly rows="3"><?=sf_escape($key)?></textarea></div><div><label for="translation-value-<?=$i?>"><?=sf_escape(sf_translation_languages()[$language])?></label><textarea id="translation-value-<?=$i?>" name="entries[<?=$i?>][value]" rows="3" maxlength="12000"><?=sf_escape($value)?></textarea></div></section><?php $i++;endforeach;?>
<details class="panel translation-new"><summary>Yeni metin için çeviri ekle</summary><div class="translation-pair"><div><label for="new-source">Sitedeki İngilizce metin (birebir)</label><textarea id="new-source" name="entries[<?=$i?>][key]" rows="3" maxlength="12000"></textarea></div><div><label for="new-value">Çevirisi</label><textarea id="new-value" name="entries[<?=$i?>][value]" rows="3" maxlength="12000"></textarea></div></div></details><button class="button">Bu sayfadaki çevirileri kaydet</button></form>
<nav class="translation-pagination" aria-label="Sayfalar"><?php if($page>1):?><a class="button button-ghost" href="?<?=http_build_query(['lang'=>$language,'q'=>$query,'page'=>$page-1])?>">Önceki</a><?php endif;?><?php if($page<$pages):?><a class="button button-ghost" href="?<?=http_build_query(['lang'=>$language,'q'=>$query,'page'=>$page+1])?>">Sonraki</a><?php endif;?></nav></main></div></body></html>
